          "limites": [
            "A fonte não identifica, nesses trechos, requisitos específicos de parada definitiva, limpeza ou descontaminação.",
            "O panorama é institucional e regulatório, não operacional."
          ]
        },
        {
          "proposicao": "O descomissionamento é definido como a última etapa de um projeto de exploração e produção de hidrocarbonetos.",
          "trechos": [
            "E3e697fd5130d58cc:0:696",
            "E3e697fd5130d58cc:1395:2089"
